    return IdentityRef(
        domain=_csil_expect_text(tree["domain"]),
        user_id=(None if tree.get("user_id") is None else _csil_expect_text(tree["user_id"])),
        handle=(None if tree.get("handle") is None else _csil_expect_text(tree["handle"])),
    )


